            candidate.waitingSince = nil
        end
    end
    if starvedOverride and (overrideRan or not isReady(starvedOverride)) then
        starvedOverride = nil
        overrideRan = false
    end
    if not starvedOverride and starved then
        starvedOverride = starved
        log(S(852) .. starved.name .. S(745)
            .. string.format(S(844), now - starved.waitingSince)
            .. S(405))
    end
    local chosen = starvedOverride or ready[1]
    if chosen then
        chosen.waitingSince = nil
    end
    return chosen
end
function scheduler.Start()
    if connection then
        return
    end
    connection = RunService.Heartbeat:Connect(function()
        for _, task_ in ipairs(standaloneTasks) do
            if task_.isEnabled() then
                run(task_)
            end
        end
        if anyExclusiveBusy() then
            if starvedOverride and starvedOverride.isBusy
                and starvedOverride.isBusy()
            then
                overrideRan = true
            end
            return
        end
        local next_ = pickExclusive()
        if next_ ~= currentTask then
            currentTask = next_
            log(S(642) .. (currentTask and currentTask.name or S(673)))
        end
        if currentTask then
            run(currentTask)
        end
    end)
end
function scheduler.Stop()
    if connection then
        connection:Disconnect()
        connection = nil
    end
    currentTask = nil
    starvedOverride = nil
    overrideRan = false
    for _, task_ in ipairs(exclusiveTasks) do
        task_.waitingSince = nil
    end
end
return scheduler
end
end
modules[S(428)] = function()
local Players = game:GetService(S(512))
local teleport = {}
local savedCFrame = nil
local function getHumanoidRootPart()
    local character = Players.LocalPlayer.Character
    return character and character:FindFirstChild(S(70))
end
function teleport.To(part, offset)
    local hrp = getHumanoidRootPart()
    if not (hrp and part) then
        return false
    end
    if not savedCFrame then
        savedCFrame = hrp.CFrame
    end
    hrp.CFrame = CFrame.new(part.Position + (offset or Vector3.new(0, 3, 5)))
    return true
end
function teleport.Return()
    local hrp = getHumanoidRootPart()
    if hrp and savedCFrame then
        hrp.CFrame = savedCFrame
    end
    savedCFrame = nil
end
function teleport.IsAway()
    return savedCFrame ~= nil
end
return teleport
end
