local gameApi = import(S(785))(import)
local log = import(S(430))
local runGuarded = import(S(208))(import)
local checkInterval = 30
local maxPerPass = 5
local buyZones = true
local buyCore = true
local coreLastResort = true
local cheapestFirst = true
local keepMoney = 0
local autoResearch = {}
local enabled = false
local busy = false
local lastAttempt = 0
local lastIdleSummary = nil
local reportIdle
function autoResearch.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    log(S(644) .. (enabled and S(205) or S(252)))
    if enabled then
        task.spawn(function()
            task.wait(1)
            if enabled then
                reportIdle()
            end
        end)
    end
end
function autoResearch.IsEnabled()
    return enabled
end
function autoResearch.IsBusy()
    return busy
end
function autoResearch.SetCheckInterval(seconds)
    checkInterval = math.max(seconds, 5)
end
function autoResearch.SetMaxPerPass(count)
    maxPerPass = math.max(count, 1)
end
function autoResearch.SetBuyZones(state)
    buyZones = state
end
function autoResearch.SetBuyCore(state)
    buyCore = state
end
function autoResearch.SetCoreLastResort(state)
    coreLastResort = state
end
function autoResearch.SetCheapestFirst(state)
    cheapestFirst = state
end
function autoResearch.SetKeepMoney(amount)
    keepMoney = math.max(amount, 0)
end
local function spendable()
    return gameApi.GetMoney() - keepMoney
end
local function buyableZoneNodes()
    local budget = spendable()
    local list = {}
    local powerBlocked = nil
    for _, zoneKey in ipairs(gameApi.UnlockedZones()) do
        for _, node in ipairs(gameApi.SkillNodes(zoneKey)) do
            if node.open and not node.maxed and node.cost and node.cost <= budget then
                table.insert(list, node)
                if not node.powerOk then
                    if not powerBlocked or node.powerReq < powerBlocked.powerReq then
                        powerBlocked = node
                    end
                end
            end
        end
    end
    return list, powerBlocked
end
local function buyableCoreNodes()
    local budget = spendable()
    local list = {}
    for _, node in ipairs(gameApi.CoreNodes()) do
        if node.open and not node.maxed and node.event
            and node.cost and node.cost <= budget
        then
            table.insert(list, node)
        end
    end
    return list
end
local function sortNodes(list)
    table.sort(list, function(a, b)
        local aPower = a.powerOk ~= false
        local bPower = b.powerOk ~= false
        if aPower ~= bPower then
            return aPower
        end
        if a.cost ~= b.cost then
            if cheapestFirst then
                return a.cost < b.cost
            end
            return a.cost > b.cost
        end
        return tostring(a.id) < tostring(b.id)
    end)
end
local function levelOfZoneNode(node)
    for _, current in ipairs(gameApi.SkillNodes(node.zoneKey)) do
        if current.id == node.id then
            return current.level
        end
    end
    return node.level
end
local function levelOfCoreNode(node)
    for _, current in ipairs(gameApi.CoreNodes()) do
        if current.id == node.id then
            return current.level
        end
    end
    return node.level
end
local function runJob()
    busy = true
    local bought = 0
    local blocked = 0
    local powerBlocked = nil
    if buyZones then
        local nodes
        nodes, powerBlocked = buyableZoneNodes()
        sortNodes(nodes)
        for _, node in ipairs(nodes) do
            if not enabled or bought >= maxPerPass then
                break
            end
            gameApi.BuySkill(node.zoneKey, node.family)
            task.wait(0.4)
            local after = levelOfZoneNode(node)
            if after > node.level then
                log(S(294) .. node.zoneKey .. S(423) .. node.id
                    .. S(958) .. node.family .. S(150) .. node.level .. S(662) .. after)
                bought = bought + 1
                lastIdleSummary = nil
            else
                blocked = blocked + 1
            end
        end
    end
    local zonesStillWant = coreLastResort and #(buyableZoneNodes()) > 0
    if buyCore and not zonesStillWant then
        local nodes = buyableCoreNodes()
        sortNodes(nodes)
        for _, node in ipairs(nodes) do
            if not enabled or bought >= maxPerPass then
                break
            end
            gameApi.BuyCore(node.event)
            task.wait(0.4)
            local after = levelOfCoreNode(node)
            if after > node.level then
                log(S(665) .. node.id
                    .. S(807) .. node.family .. S(91) .. node.level .. S(791) .. after)
                bought = bought + 1
                lastIdleSummary = nil
            else
                blocked = blocked + 1
            end
        end
    end
    if bought == 0 then
        if blocked > 0 then
            log(S(789) .. blocked
                .. S(138))
        elseif powerBlocked then
            log(S(119) .. powerBlocked.zoneKey .. S(445) .. powerBlocked.id
                .. S(558) .. powerBlocked.family .. S(53)
                .. math.floor(powerBlocked.powerReq) .. S(303)
                .. math.floor(powerBlocked.power)
                .. S(894))
        else
            log(S(897)
                .. S(45) .. math.floor(gameApi.GetMoney()) .. S(256))
            local nearest = nil
            for _, zoneKey in ipairs(gameApi.UnlockedZones()) do
                for _, node in ipairs(gameApi.SkillNodes(zoneKey)) do
                    if node.open and not node.maxed and node.cost
                        and (not nearest or node.cost < nearest.cost)
                    then
                        nearest = node
                    end
                end
            end
            if nearest then
                log(S(598) .. nearest.zoneKey
                    .. S(603) .. nearest.id .. S(486) .. nearest.family .. S(226)
                    .. nearest.level .. S(242) .. nearest.max
                    .. S(97) .. math.floor(nearest.cost))
            end
        end
    end
    busy = false
end
local function idleSummary()
    if not buyZones and not buyCore then
        return S(564)
    end
    local money = gameApi.GetMoney()
    local budget = spendable()
    local nearest = nil
    if buyZones then
        for _, zoneKey in ipairs(gameApi.UnlockedZones()) do
            for _, node in ipairs(gameApi.SkillNodes(zoneKey)) do
                if node.open and not node.maxed and node.cost
                    and (not nearest or node.cost < nearest.cost)
                then
                    nearest = node
                end
            end
        end
    end
    if buyCore then
        for _, node in ipairs(gameApi.CoreNodes()) do
            if node.open and not node.maxed and node.cost
                and (not nearest or node.cost < nearest.cost)
            then
                nearest = {
                    zoneKey = S(810),
                    id = node.id,
                    family = node.family,
                    level = node.level,
                    max = node.level + 1,
                    cost = node.cost,
                    powerOk = true,
                }
            end
        end
    end
    if not nearest then
        local parts = {}
        if not buyZones then
            table.insert(parts, S(895))
        end
        if not buyCore then
            table.insert(parts, S(790))
        end
        if #parts == 0 then
            return S(11)
        end
        return S(832) .. table.concat(parts, S(515)) .. S(498)
    end
    local why
    if nearest.cost > budget then
        why = S(337) .. string.format(S(362), nearest.cost)
            .. S(298) .. string.format(S(351), money)
    elseif nearest.powerOk == false then
        why = S(40) .. string.format(S(52), nearest.powerReq) .. S(154)
    else
        why = S(551)
    end
    return S(510) .. nearest.zoneKey .. S(675) .. tostring(nearest.id)
        .. S(344) .. tostring(nearest.family) .. S(671) .. why
end
function reportIdle()
    local summary = idleSummary()
    if summary == lastIdleSummary then
        return
    end
    lastIdleSummary = summary
    log(S(322) .. summary)
end
local lastIdleReport = 0
function autoResearch.HasWork()
    local zoneNodes = buyZones and buyableZoneNodes() or {}
    local has
    if #zoneNodes > 0 then
        has = true
    elseif not buyCore then
        has = false
    else
        has = #buyableCoreNodes() > 0
    end
    if not has and enabled then
        local now = tick()
        if now - lastIdleReport >= math.max(checkInterval, 15) then
            lastIdleReport = now
            reportIdle()
        end
    end
    return has
end
function autoResearch.Step()
    if not enabled or busy then
        return
    end
    local now = tick()
    if now - lastAttempt < checkInterval then
        return
    end
    lastAttempt = now
    runGuarded(S(257), runJob, function()
        busy = false
    end)
end
return autoResearch
end
end
modules[S(553)] = function()
return function(import)
local Workspace = game:GetService(S(925))
local gameApi = import(S(366))(import)
local teleport = import(S(707))
local log = import(S(462))
local runGuarded = import(S(299))(import)
local checkInterval = 45
local autoSell = {}
local enabled = false
local busy = false
local lastAttempt = 0
local holdWhile = nil
local needsProximity = nil
function autoSell.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    if not enabled then
        if not busy then
            teleport.Return()
        end
        log(S(342))
    else
        lastAttempt = 0
        log(S(825))
    end
end
function autoSell.IsEnabled()
    return enabled
end
function autoSell.IsBusy()
    return busy
end
function autoSell.SetCheckInterval(seconds)
    checkInterval = math.max(seconds, 5)
end
function autoSell.SetHoldWhile(predicate)
    holdWhile = predicate
end
function autoSell.HasWork()
    if holdWhile and holdWhile() then
        return false
    end
    return #gameApi.SellableKeys() > 0
end
local function getSellStandPart()
    local sellStand = Workspace:FindFirstChild(S(350))
    local prompt = sellStand and sellStand:FindFirstChildWhichIsA(S(133), true)
    return prompt and prompt.Parent
end
local function sell(keys)
    gameApi.SellItems(keys)
    task.wait(0.6)
    return #gameApi.SellableKeys() < #keys
end
local function runJob()
    busy = true
    local keys = gameApi.SellableKeys()
    if #keys == 0 then
        busy = false
        return
    end
    local sold = false
    if needsProximity ~= true then
        sold = sell(keys)
        if needsProximity == nil then
            needsProximity = not sold
            log(S(195)
                .. (sold and S(255)
                         or S(27)))
        end
    end
    if not sold then
        local part = getSellStandPart()
        if part then
            teleport.To(part)
            task.wait(0.4)
            sold = sell(gameApi.SellableKeys())
            teleport.Return()
        end
    end
    log(S(582) .. (sold and (S(367) .. #keys .. S(535)) or S(80)))
    busy = false
end
function autoSell.Step()
    if not enabled or busy then
        return
    end
    local now = tick()
    if now - lastAttempt < checkInterval then
        return
    end
    lastAttempt = now
    if #gameApi.SellableKeys() == 0 then
        return
    end
    runGuarded(S(663), runJob, function()
        busy = false
    end)
end
return autoSell
end
end
modules[S(174)] = function()
return function(import)
local Workspace = game:GetService(S(736))
local gameApi = import(S(548))(import)
local teleport = import(S(685))
local log = import(S(703))
local runGuarded = import(S(640))(import)
local STATS = { S(346), S(413), S(904) }
local checkInterval = 20
local maxPerPass = 5
local priority = S(368)
local keepMoney = 0
local buyPickaxe = true
local pickaxeTarget = 0
local equipPickaxes = true
local limitToHolders = true
local rollMutations = false
local mutationTarget = 2
local mutationBudget = 0
local autoUpgrade = {}
local enabled = false
local busy = false
local lastAttempt = 0
local reportedCap = false
function autoUpgrade.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    log(S(681) .. (enabled and S(491) or S(836)))
end
function autoUpgrade.IsEnabled()
    return enabled
end
function autoUpgrade.IsBusy()
    return busy
end
function autoUpgrade.SetInterval(seconds)
    checkInterval = math.max(seconds, 1)
end
function autoUpgrade.SetMaxPerPass(count)
    maxPerPass = math.max(count, 1)
end
function autoUpgrade.SetPriority(value)
    priority = value
end
function autoUpgrade.SetKeepMoney(amount)
    keepMoney = math.max(amount, 0)
end
function autoUpgrade.SetBuyPickaxe(state)
    buyPickaxe = state
end
function autoUpgrade.SetPickaxeTarget(index)
    pickaxeTarget = index
end
function autoUpgrade.SetEquipPickaxes(state)
    equipPickaxes = state
end
function autoUpgrade.SetLimitPickaxesToHolders(state)
    limitToHolders = state
end
function autoUpgrade.SetRollMutations(state)
    rollMutations = state
end
function autoUpgrade.SetMutationTarget(multiplier)
    mutationTarget = math.max(multiplier, 1)
end
function autoUpgrade.SetMutationBudget(amount)
    mutationBudget = math.max(amount, 0)
end
local function holders()
    local mine = gameApi.GetMineData()
    return mine and mine.Holders or {}
end
local function holderKeys()
    local keys = {}
    for holderKey, entry in pairs(holders()) do
        if type(entry) == S(474) and entry.CharName then
            table.insert(keys, holderKey)
        end
    end
    table.sort(keys)
    return keys
end
local function spendable()
    return gameApi.GetMoney() - keepMoney
end
local function chooseStat(holderKey)
    local budget = spendable()
    local anyLeft = false
    local preferred = nil
    local lowest = nil
    for _, stat in ipairs(STATS) do
        local info = gameApi.StatInfo(holderKey, stat)
        if info and not info.maxed and info.cost then
            anyLeft = true
            if info.cost <= budget then
                if stat == priority then
                    preferred = { stat = stat, info = info }
                end
                if not lowest or info.level < lowest.info.level then
                    lowest = { stat = stat, info = info }
                end
            end
        end
    end
    local choice = preferred or lowest
    if choice then
        return choice
    end
    return nil, anyLeft and S(759) or S(216)
end
local function upgradeStats()
    local bought = 0
    local tooExpensive = 0
    local maxed = 0
    while enabled and bought < maxPerPass do
        local boughtThisLap = 0
        for _, holderKey in ipairs(holderKeys()) do
            if not enabled or bought >= maxPerPass then
                break
            end
            local choice, reason = chooseStat(holderKey)
            if choice then
                gameApi.UpgradeCharacter(holderKey, choice.stat)
                task.wait(0.35)
                local after = gameApi.StatInfo(holderKey, choice.stat)
                if after and after.level > choice.info.level then
                    log(S(767) .. holderKey .. S(277) .. choice.stat .. S(699)
                        .. choice.info.level .. S(5) .. after.level
                        .. S(411) .. after.max)
                    bought = bought + 1
                    boughtThisLap = boughtThisLap + 1
                end
            elseif reason == S(117) then
                tooExpensive = tooExpensive + 1
            else
                maxed = maxed + 1
            end
        end
        if boughtThisLap == 0 then
            break
        end
    end
    return bought, tooExpensive, maxed
end
local function pickaxeCapReached()
    if not limitToHolders then
        return false
    end
    local cap = gameApi.MaxMinerSlots()
    if cap <= 0 then
        cap = gameApi.MinerSlots()
    end
    if cap <= 0 then
        return false
    end
    return gameApi.OwnedPickaxeCount() >= cap
end
local function findPickaxe()
    if pickaxeCapReached() then
        return nil
    end
    if pickaxeTarget > 0 then
        for _, pickaxe in ipairs(gameApi.GetPickaxes()) do
            if pickaxe.index == pickaxeTarget then
                if pickaxe.zoneUnlocked and pickaxe.inStock
                    and pickaxe.cost <= spendable()
                then
                    return pickaxe
                end
                return nil
            end
        end
        return nil
    end
    local wanted = gameApi.WantedPickaxe()
    if wanted and wanted.cost <= spendable() then
        return wanted
    end
    return nil
end
local function ownedCountOf(name)
    for _, pickaxe in ipairs(gameApi.GetPickaxes()) do
        if pickaxe.name == name then
            return pickaxe.ownedCount
        end
    end
    return 0
end
local function getPickaxeStandPart()
    local stand = Workspace:FindFirstChild(S(492))
    local shop = stand and stand:FindFirstChild(S(575))
    if not shop then
        return nil
    end
    if shop:IsA(S(46)) then
        return shop
    end
    return shop:FindFirstChildWhichIsA(S(933), true)
end
local needsProximity = nil
local function sendBuy(pickaxe)
    local before = ownedCountOf(pickaxe.name)
    gameApi.BuyPickaxe(pickaxe.index)
    task.wait(0.4)
    return ownedCountOf(pickaxe.name) > before
end
local function tryPickaxe()
    local pickaxe = findPickaxe()
    if not pickaxe then
        return false
    end
    local bought = false
    if needsProximity ~= true then
        bought = sendBuy(pickaxe)
        if needsProximity == nil then
            needsProximity = not bought
            log(S(540)
                .. (bought and S(392)
                           or S(232)))
        end
    end
    if not bought then
        local part = getPickaxeStandPart()
        if part then
            teleport.To(part)
            task.wait(0.4)
            bought = sendBuy(pickaxe)
            teleport.Return()
            if not bought then
                needsProximity = nil
            end
        else
            log(S(238))
        end
    end
    if bought then
        log(S(239) .. pickaxe.index .. S(394) .. pickaxe.name
            .. S(867) .. pickaxe.multiplier .. S(943))
        return true
    end
    log(S(356) .. pickaxe.index .. S(855) .. pickaxe.name
        .. S(389))
    return false
end
local function plannedPickaxes()
    local pool = gameApi.OwnedPickaxePool()
    local keys = holderKeys()
    if #pool == 0 or #keys == 0 then
        return {}
    end
    table.sort(keys, function(a, b)
        local da = gameApi.HolderBaseDamage(a) or 0
        local db = gameApi.HolderBaseDamage(b) or 0
        if da ~= db then
            return da > db
        end
        return a < b
    end)
    local plan = {}
    for position, holderKey in ipairs(keys) do
        local wanted = pool[position]
        if not wanted then
            break
        end
        table.insert(plan, { holderKey = holderKey, pickaxe = wanted })
    end
    return plan
end
local function pickaxeAssignmentPending()
    local current = holders()
    for _, step in ipairs(plannedPickaxes()) do
        local entry = current[step.holderKey]
        if (entry and entry.Pickaxe or nil) ~= step.pickaxe.name then
            return true
        end
    end
    return false
end
local function equipPickaxesBestFirst()
    local current = holders()
    for _, step in ipairs(plannedPickaxes()) do
        local holderKey, wanted = step.holderKey, step.pickaxe
        local entry = current[holderKey]
        local worn = entry and entry.Pickaxe or nil
        if worn ~= wanted.name then
            gameApi.EquipPickaxe(holderKey, wanted.name)
            task.wait(0.3)
            local after = holders()[holderKey]
            local nowWorn = after and after.Pickaxe or nil
            if nowWorn == wanted.name then
                log(S(631) .. holderKey .. S(643)
                    .. tostring(worn or S(157)) .. S(800) .. wanted.name)
            else
                log(S(449) .. holderKey .. S(577)
                    .. wanted.name .. S(884) .. tostring(nowWorn or S(286)) .. S(698))
            end
        end
    end
end
local function rollMutationsPass(remaining)
    local rolled = 0
    for _, holderKey in ipairs(holderKeys()) do
        if not enabled or rolled >= remaining then
            break
        end
        local variant = gameApi.HolderVariantMult(holderKey)
        local cost = gameApi.MutationRollCost(holderKey)
        if variant < mutationTarget and cost
            and cost <= spendable()
            and (mutationBudget == 0 or cost <= mutationBudget)
        then
            gameApi.RollMutation(holderKey)
            task.wait(0.5)
            local after = gameApi.HolderVariantMult(holderKey)
            log(S(381) .. holderKey .. S(873) .. variant
                .. S(320) .. after .. S(646) .. cost .. S(339))
            rolled = rolled + 1
        end
    end
    return rolled
end
local function runJob()
    busy = true
    local bought, tooExpensive, maxed = upgradeStats()
    if buyPickaxe and enabled and bought < maxPerPass then
        if pickaxeCapReached() then
            if not reportedCap then
                log(S(72) .. gameApi.OwnedPickaxeCount()
                    .. S(376) .. gameApi.MaxMinerSlots()
                    .. S(952))
                reportedCap = true
            end
        elseif tryPickaxe() then
            bought = bought + 1
            reportedCap = false
        end
    end
    if equipPickaxes and enabled then
        equipPickaxesBestFirst()
    end
    if rollMutations and enabled and bought < maxPerPass then
        bought = bought + rollMutationsPass(maxPerPass - bought)
    end
    if bought == 0 then
        if tooExpensive > 0 then
            log(S(285))
        elseif maxed > 0 then
            log(S(127))
        else
            log(S(846))
        end
    end
    busy = false
end
function autoUpgrade.HasWork()
    for _, holderKey in ipairs(holderKeys()) do
        if chooseStat(holderKey) then
            return true
        end
    end
    if buyPickaxe and findPickaxe() then
        return true
    end
    if equipPickaxes and pickaxeAssignmentPending() then
        return true
    end
    if rollMutations then
        for _, holderKey in ipairs(holderKeys()) do
            local cost = gameApi.MutationRollCost(holderKey)
            if gameApi.HolderVariantMult(holderKey) < mutationTarget
                and cost and cost <= spendable()
                and (mutationBudget == 0 or cost <= mutationBudget)
            then
                return true
            end
        end
    end
    return false
end
function autoUpgrade.Step()
    if not enabled or busy then
        return
    end
    local now = tick()
    if now - lastAttempt < checkInterval then
        return
    end
    lastAttempt = now
    runGuarded(S(913), runJob, function()
        busy = false
    end)
end
return autoUpgrade
end
end
modules[S(379)] = function()
return function(import)
local ReplicatedStorage = game:GetService(S(125))
local Workspace = game:GetService(S(274))
local log = import(S(804))
local api = {}
local protectUsefulUnits = true
local gameState, mineInventory, mineConfig, mineStock, items, indexRewards
local loadFailed = false
local function modules()
    if gameState or loadFailed then
        return gameState ~= nil
    end
    local ok, err = pcall(function()
        local moduleFolder = ReplicatedStorage:WaitForChild(S(99), 5)
        gameState = require(moduleFolder.GameState)
        mineInventory = require(moduleFolder.MineInventory)
        mineConfig = require(moduleFolder.MineConfig)
        mineStock = require(moduleFolder.MineStock)
        items = require(moduleFolder.Items)
        indexRewards = require(moduleFolder.MineIndexRewardsConfig)
    end)
    if not ok then
        loadFailed = true
        log(S(942) .. tostring(err))
        return false
    end
    return true
end
function api.SetProtectUsefulUnits(state)
    protectUsefulUnits = state
end
function api.IsReady()
    return modules()
end
function api.GetData()
    if not modules() then
        return nil
    end
    local ok, data = pcall(gameState.GetData2)
    if not ok then
        return nil
    end
    return data
end
function api.GetMineData()
    local data = api.GetData()
    return data and data.MineGame or nil
end
function api.GetMoney()
    local data = api.GetData()
    return data and tonumber(data.Money) or 0
end
function api.GetPickaxes()
    if not modules() then
        return {}
    end
    local data = api.GetData()
    local mine = data and data.MineGame
    local owned = (mine and mine.Pickaxes) or {}
    local unlocked = (mine and mine.UnlockedZones) or {}
    local list = {}
    local ok = pcall(function()
        for index, def in ipairs(mineConfig.Pickaxes) do
            local buyableWithCash = not (mineConfig.IsPickaxeFree(def)
                or def.RobuxOnly or type(def.Stock) ~= S(802))
            if buyableWithCash then
                local remaining = nil
                if data then
                    local gotStock, value = pcall(mineStock.GetRemaining, data, def.Name)
                    remaining = gotStock and value or nil
                end
                local zoneOpen = unlocked[def.ZoneReq] and true or false
                table.insert(list, {
                    index = index,
                    name = def.Name,
