end
local reported = {}
local function getContainer()
    local playerGui = Players.LocalPlayer:FindFirstChild(S(377))
    local mineGui = playerGui and playerGui:FindFirstChild(S(920))
    local hotbar = mineGui and mineGui:FindFirstChild(S(773))
    local content = hotbar and hotbar:FindFirstChild(S(37))
    return content and content:FindFirstChild(S(859))
